"""Driver for the Brevalt KX-100 RF power meter. The programming manual is MANUAL.md.

`session` is an open connection to the meter with three methods:
    session.write(cmd: str) -> None
    session.read() -> str
    session.query(cmd: str) -> str      # write, then read
"""

import math

# The queue holds 10 errors; read a few more than that so a full queue is always drained.
_MAX_ERROR_READS = 32
_OVER_RANGE = 9.9e37


class InstrumentError(Exception):
    """The meter reported an error: SYST:ERR? returned a code other than 0."""


def _drain_errors(session) -> list:
    """Read SYST:ERR? until it returns code 0; return the list of (code, text) read."""
    errors = []
    for _ in range(_MAX_ERROR_READS):
        response = session.query("SYST:ERR?").strip()
        code_text, _, text = response.partition(",")
        try:
            code = int(code_text.strip())
        except ValueError as e:
            raise InstrumentError(f"unparseable SYST:ERR? response: {response!r}") from e
        if code == 0:
            return errors
        errors.append((code, text.strip().strip('"')))
    raise InstrumentError(f"error queue did not empty: {errors}")


def _format_freq(freq_hz) -> str:
    value = float(freq_hz)
    if not math.isfinite(value):
        raise InstrumentError(f"invalid frequency: {freq_hz!r}")
    if value.is_integer():
        return str(int(value))
    return repr(value)


def _format_count(averages) -> str:
    if isinstance(averages, bool):
        raise InstrumentError(f"invalid averaging count: {averages!r}")
    if isinstance(averages, int):
        return str(averages)
    if isinstance(averages, float) and averages.is_integer():
        return str(int(averages))
    return str(averages)  # the meter refuses it with -104, reported below


def measure_power(session, freq_hz: float, averages: int) -> float:
    """Measure the power of a signal at `freq_hz`, averaging `averages` readings, and return it in dBm.

    Raise InstrumentError if the meter reports any error while configuring or measuring.
    """
    session.write("*CLS")
    session.write(f"SENS:FREQ {_format_freq(freq_hz)}")
    session.write(f"SENS:AVER:COUN {_format_count(averages)}")
    session.write("CONF:POW:RANG AUTO")
    session.write("INIT")

    opc = session.query("*OPC?").strip()
    if opc != "1":
        _drain_errors(session)
        raise InstrumentError(f"unexpected *OPC? response: {opc!r}")

    raw = session.query("FETC?").strip()

    errors = _drain_errors(session)
    if errors:
        desc = "; ".join(f"{code},\"{text}\"" for code, text in errors)
        raise InstrumentError(f"KX-100 reported error(s): {desc}")

    try:
        value = float(raw)
    except ValueError as e:
        raise InstrumentError(f"unparseable FETC? response: {raw!r}") from e
    if not math.isfinite(value) or value >= _OVER_RANGE:
        raise InstrumentError(f"measurement over range: {raw!r}")
    return value
